mapper.select:
/* CastSmltMapper.retrieveSmltStng */
SELECT
    SMLT_ID, SMLT_MDL_SN, SMLT_NM, SMLT_TYPE, CRTR_DT, EXCN_YMD, TMNL_ID, SLF_ID, PRNT_ID,
    FLT_SCHDL_RSRC_ID, BAG_ALCTN_RSRC_ID, CKNCT_ALCTN_RSRC_ID, PRPT_SET_RSRC_ID, MDL_RSRC_ID,
    EXCN_ID, CKNCT_SRVC_HR_RSRC_ID, CHKN_TYPE_RSRC_ID, FCLTY_OPNG_DPTCNY_SRNG_RSRC_ID,
    FCLTY_OPNG_EMI_RSRC_ID, FCLTY_OPNG_IMMI_RSRC_ID,
    FCLTY_OPNG_SCRTY_CNTRL_RSRC_ID, FCLTY_OPNG_TR_SCRTY_CNTRL_RSRC_ID,
    SBD_CNTRL_ALCTN_ID, PLAN_BGNG_DT, PLAN_END_DT, SMLT_BGNG_DT, SMLT_END_DT, BDPSG_ANCE_YN
FROM PMOWN.TN_PM_SMLT_STNG
WHERE 1 = 1

AND SMLT_ID = #{smltId}


AND EXCN_YMD = #{excnYmd}


AND SMLT_TYPE = #{smltType}

/* CastSmltMapper.retrieveUserSmltCondFilledCnt */

SELECT COUNT(*) AS CNT
FROM (
    SELECT 1 FROM DUAL
    WHERE EXISTS (
        SELECT 1 FROM PMOWN.TN_PM_SMLT_USER_FLT_PSG_AJMT
        WHERE SMLT_ID = #{smltId} AND TMNL_ID = #{tmnlId}
    )
    AND EXISTS (
        SELECT 1 FROM PMOWN.TN_PM_SMLT_USER_CHKN_ISL
        WHERE SMLT_ID = #{smltId} AND TMNL_ID = #{tmnlId}
    )
    AND EXISTS (
        SELECT 1 FROM PMOWN.TN_PM_SMLT_USER_DPTGT
        WHERE SMLT_ID = #{smltId} AND TMNL_ID = #{tmnlId}
    )
)

/* CastSmltMapper.retrieveUserSmltSaveDt */

SELECT NVL(TO_CHAR(MAX(A.SAVE_DT), 'YYYYMMDDHH24MISS'), '') AS SAVE_DT
FROM (
    SELECT MAX(NVL(LAST_MDFCN_DT, FRST_REG_DT)) AS SAVE_DT
    FROM PMOWN.TN_PM_SMLT_USER_FLT_PSG_AJMT
    WHERE SMLT_ID = #{smltId}
    AND TMNL_ID = #{tmnlId}
    UNION ALL
    SELECT MAX(NVL(LAST_MDFCN_DT, FRST_REG_DT)) AS SAVE_DT
    FROM PMOWN.TN_PM_SMLT_USER_CHKN_ISL
    WHERE SMLT_ID = #{smltId}
    AND TMNL_ID = #{tmnlId}
    UNION ALL
    SELECT MAX(NVL(LAST_MDFCN_DT, FRST_REG_DT)) AS SAVE_DT
    FROM PMOWN.TN_PM_SMLT_USER_DPTGT
    WHERE SMLT_ID = #{smltId}
    AND TMNL_ID = #{tmnlId}
) A

/* CastSmltMapper.retrieveNextSmltFlfmtSn */

SELECT NVL(MAX(A.SMLT_FLFMT_SN), 0) + 1 AS SMLT_FLFMT_SN
FROM PMOWN.TH_PM_SMLT_FLFMT_HSTRY A
WHERE A.SMLT_ID = #{smltId}

mapper.update:
/* CastSmltMapper.updateSmltFlfmtClosed */

UPDATE PMOWN.TH_PM_SMLT_FLFMT_HSTRY
SET SMLT_FLFMT_STTS_CD = #{smltFlfmtSttsCd},
    SMLT_FLFMT_END_DT = CURRENT_TIMESTAMP,
    LAST_MDFR_ID = 'CAST',
    LAST_MDFCN_DT = CURRENT_TIMESTAMP
WHERE SMLT_ID = #{smltId}
AND SMLT_FLFMT_SN = #{smltFlfmtSn}
AND SMLT_FLFMT_STTS_CD = 'RUNNING'

mapper.select:
/* CastSmltMapper.retrieveSmltFlfmt */
SELECT * FROM ( SELECT A.SMLT_ID, A.SMLT_FLFMT_SN, A.TMNL_ID, A.SMLT_TYPE, A.SMLT_FLFMT_STTS_CD, TO_CHAR(A.SMLT_FLFMT_BGNG_DT, 'YYYYMMDDHH24MISS') AS SMLT_FLFMT_BGNG_DT, NVL(TO_CHAR(A.SMLT_FLFMT_END_DT, 'YYYYMMDDHH24MISS'), '') AS SMLT_FLFMT_END_DT, NVL(ROUND((CAST(A.SMLT_FLFMT_END_DT AS DATE) - CAST(A.SMLT_FLFMT_BGNG_DT AS DATE)) * 1440), 0) AS EXEC_MIN, A.FRST_RGTR_ID AS RGTR_ID, NVL(B.EXCN_YMD, '') AS EXCN_YMD, NVL(D.DEPT_NM, '') AS DEPT_NM, NVL(C.USER_NM, '') AS USER_NM FROM PMOWN.TH_PM_SMLT_FLFMT_HSTRY A LEFT OUTER JOIN PMOWN.TN_PM_SMLT_STNG B ON A.SMLT_ID = B.SMLT_ID LEFT OUTER JOIN CAOWN.TN_CA_USER C ON A.FRST_RGTR_ID = C.USER_ID LEFT OUTER JOIN CAOWN.TN_CA_DEPT D ON C.DEPT_CD = D.DEPT_CD WHERE 1 = 1 AND A.SMLT_ID = #{smltId}
AND A.SMLT_FLFMT_SN = #{smltFlfmtSn}
ORDER BY A.SMLT_FLFMT_SN DESC ) WHERE ROWNUM = 1
